"use client";
import { useState, useRef } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { Accordion, AccordionItem, AccordionTrigger, AccordionContent } from "@/components/ui/accordion";
import { Input } from "@/components/ui/input";
import { Search } from "lucide-react";
import { useRouter } from "next/navigation";

const MOCK_CONSULTATIONS = [
  {
    id: 1,
    date: "2024-06-01T10:00:00Z",
    doctor: {
      name: "Dr. Mehta",
      specialization: "Cardiologist",
      avatar: "https://randomuser.me/api/portraits/men/32.jpg",
    },
    summary: "Routine checkup. Blood pressure slightly elevated. Advised dietary changes.",
    prescription: true,
  },
  {
    id: 2,
    date: "2024-05-15T15:30:00Z",
    doctor: {
      name: "Dr. Sharma",
      specialization: "Dermatologist",
      avatar: "https://randomuser.me/api/portraits/women/44.jpg",
    },
    summary: "Skin rash diagnosed as eczema. Prescribed topical ointment.",
    prescription: true,
  },
  {
    id: 3,
    date: "2024-04-10T09:00:00Z",
    doctor: {
      name: "Dr. Patel",
      specialization: "Pediatrician",
      avatar: "https://randomuser.me/api/portraits/men/65.jpg",
    },
    summary: "Follow-up for allergy symptoms. No new issues reported.",
    prescription: false,
  },
];

const MOCK_REPORTS = [
  {
    id: 1,
    name: "Blood_Test_Report.pdf",
    date: "2024-05-20",
    type: "pdf",
    url: "#",
  },
  {
    id: 2,
    name: "Xray_Chest.png",
    date: "2024-05-10",
    type: "image",
    url: "#",
  },
];

const FILE_ICONS = {
  pdf: (
    <svg className="w-5 h-5 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M6 2a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8.828A2 2 0 0 0 19.414 8L14 2.586A2 2 0 0 0 12.586 2H6z" /><path d="M14 2v6h6" /></svg>
  ),
  image: (
    <svg className="w-5 h-5 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><rect width="20" height="14" x="2" y="5" rx="2" /><circle cx="8.5" cy="10.5" r="1.5" /><path d="M21 19l-5.5-5.5a2 2 0 0 0-2.8 0L3 19" /></svg>
  ),
};

function formatDateTime(dt) {
  const d = new Date(dt);
  return d.toLocaleString(undefined, { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit" });
}

export default function HealthHistoryPage() {
  const [consultations, setConsultations] = useState(MOCK_CONSULTATIONS);
  const [reports, setReports] = useState(MOCK_REPORTS);
  const [search, setSearch] = useState("");
  const [tab, setTab] = useState("consultations");
  const fileInputRef = useRef();
  const router = useRouter();


  // Filter consultations by doctor name or date
  const filteredConsultations = consultations.filter((c) =>
    c.doctor.name.toLowerCase().includes(search.toLowerCase()) ||
    formatDateTime(c.date).toLowerCase().includes(search.toLowerCase())
  );

  // Handle file upload (mock)
  const handleUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const type = file.type.includes("pdf") ? "pdf" : "image";
    setReports([
      ...reports,
      {
        id: Date.now(),
        name: file.name,
        date: new Date().toISOString().slice(0, 10),
        type,
        url: "#",
      },
    ]);
  };

  // Handle delete report (mock)
  const handleDelete = (id) => {
    setReports(reports.filter((r) => r.id !== id));
  };

  return (
    <div className="w-full mx-auto px-2">
      <h1 className="text-3xl font-bold mb-6 text-blue-600">Health History</h1>
      <Tabs value={tab} onValueChange={setTab} className="mb-6">
        <TabsList>
          <TabsTrigger value="consultations">Consultation Timeline</TabsTrigger>
          <TabsTrigger value="reports">Uploaded Reports</TabsTrigger>
        </TabsList>
        <TabsContent value="consultations">
          <Card className="mb-6 p-4">
            <div className="flex items-center gap-2 mb-4">
              <Search className="text-gray-400" size={18} />
              <Input
                placeholder="Search by doctor or date..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full max-w-xs"
              />
            </div>
            {filteredConsultations.length === 0 ? (
              <div className="flex flex-col items-center py-12">
                <span className="text-6xl mb-4">🩺</span>
                <div className="text-gray-500 text-lg">No consultations found.</div>
              </div>
            ) : (
              <Accordion type="multiple" className="w-full">
                {filteredConsultations.map((c) => (
                  <AccordionItem key={c.id} value={String(c.id)}>
                    <AccordionTrigger>
                      <div className="flex items-center gap-4">
                        <Avatar className="w-10 h-10">
                          <AvatarImage src={c.doctor.avatar} alt={c.doctor.name} />
                          <AvatarFallback>{c.doctor.name.charAt(0)}</AvatarFallback>
                        </Avatar>
                        <div>
                          <div className="font-semibold text-2xl text-gray-800">{c.doctor.name}</div>
                          <div className="text-blue-600 text-l">{c.doctor.specialization}</div>
                        </div>
                        <Badge color="gray" className="ml-4 text-base">{formatDateTime(c.date)}</Badge>
                      </div>
                    </AccordionTrigger>
                    <AccordionContent>
                      <div className="mb-2 text-sm text-gray-700">{c.summary}</div>
                      {c.prescription && (
                        <Button size="sm" className="bg-blue-600 text-white hover:bg-blue-700" onClick={() => router.push(`/patient/health-history/prescription`)}
                        >View Prescription</Button>
                      )}
                    </AccordionContent>
                  </AccordionItem>
                ))}
              </Accordion>
            )}
          </Card>
        </TabsContent>
        <TabsContent value="reports">
          <Card className="mb-6 p-4">
            <div className="flex items-center justify-between mb-4">
              <div className="font-semibold text-lg text-gray-800">Uploaded Reports</div>
              <Button
                variant="outline"
                onClick={() => fileInputRef.current.click()}
                className="ml-2"
              >
                Upload Report
              </Button>
              <input
                type="file"
                accept="application/pdf,image/*"
                ref={fileInputRef}
                className="hidden"
                onChange={handleUpload}
              />
            </div>
            {reports.length === 0 ? (
              <div className="flex flex-col items-center py-12">
                <span className="text-6xl mb-4">📄</span>
                <div className="text-gray-500 text-lg">No reports uploaded yet.</div>
              </div>
            ) : (
              <div className="divide-y divide-gray-100">
                {reports.map((r) => (
                  <div key={r.id} className="flex items-center gap-4 py-3">
                    <div>{FILE_ICONS[r.type]}</div>
                    <div className="flex-1">
                      <div className="font-medium text-gray-800">{r.name}</div>
                      <div className="text-xs text-gray-500">Uploaded: {r.date}</div>
                    </div>
                    <Button size="sm" variant="outline" className="mr-2">View</Button>
                    <Button size="sm" variant="destructive" onClick={() => handleDelete(r.id)}>Delete</Button>
                  </div>
                ))}
              </div>
            )}
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
} 